const items = $json.items || [];
const fulfilledItems = items.filter(item => item.status === 'fulfilled');
const backorderedItems = items.filter(item => item.status === 'backordered');

let itemsHtml = '<h3>Order Items:</h3><ul>';
items.forEach(item => {
  const icon = item.status === 'fulfilled' ? '✓' : '⏳';
  itemsHtml += `<li>${icon} ${item.productName || 'Product'} - Qty: ${item.quantity} - ${item.status.toUpperCase()}</li>`;
});
itemsHtml += '</ul>';

const backorderNote = backorderedItems.length > 0 ? 
  '<p><strong>Note:</strong> Some items are backordered and will be shipped separately.</p>' : '';

const emailBody = `
Dear ${$json.customerName},

Thank you for your order! Here's a summary of your purchase:

Order ID: ${$json.orderId}
Status: ${$json.status}
Total Items: ${items.length}
Fulfilled: ${fulfilledItems.length}
Backordered: ${backorderedItems.length}

${itemsHtml}
${backorderNote}

We will keep you updated on your order status.

Best regards,
AutoCart Team
`;

return {
  orderId: $json.orderId,
  customerName: $json.customerName,
  customerEmail: $json.customerEmail,
  orderStatus: $json.status,
  emailSubject: `Order Confirmation - ${$json.orderId}`,
  emailBody: emailBody,
  itemCount: items.length,
  fulfilledCount: fulfilledItems.length,
  backorderedCount: backorderedItems.length
};

console.error(`Failed to send email to ${$json.customerEmail}: ${$json.error}`);

return {
  emailFailed: true,
  customerEmail: $json.customerEmail,
  orderId: $json.orderId,
  error: $json.error || 'Email send failed'
};
